    padding: 0 0 22px 16px;
    background: url("data:image/jpeg;base64,") center top / auto 100% no-repeat;
    -webkit-mask-image: linear-gradient(90deg, transparent calc(50% - 92px), #000 calc(50% - 64px), #000 calc(50% + 64px), transparent calc(50% + 92px)), linear-gradient(180deg, transparent 0, #000 10%, #000 80%, transparent 100%);
    -webkit-mask-composite: source-in;
    mask-image: linear-gradient(90deg, transparent calc(50% - 92px), #000 calc(50% - 64px), #000 calc(50% + 64px), transparent calc(50% + 92px)), linear-gradient(180deg, transparent 0, #000 10%, #000 80%, transparent 100%);
    mask-composite: intersect;
    font: 400 15px/1 var(--zr-deco);
    letter-spacing: .14em;
    color: var(--zr-gold);
    text-shadow: 0 2px 10px #000;
}

#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--zr-dim);
    font-family: var(--zr-label);
    letter-spacing: .08em;
}

#completion_prompt_manager .completion_prompt_manager_list_head {
    font-family: var(--zr-label);
    letter-spacing: .2em;
    color: var(--zr-dim);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: rgba(255, 255, 255, .035);
    border: 0;
    border-radius: 0;
    margin-bottom: 4px;
    padding: 6px 8px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:nth-child(odd) {
    background: rgba(255, 255, 255, .065);
}

/* 关闭的条目不变灰：字色与开启一致，只靠开关的形状区分 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border: 0;
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--zr-text);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--zr-text);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: var(--zr-gold);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
    opacity: 1;
    filter: none;
}

/* 开关：开 = 全食，关 = 太阳 */
#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action {
    display: inline-block;
    width: 20px;
    height: 20px;
    font-size: 0;
    vertical-align: middle;
    background: var(--zr-sun) center / contain no-repeat;
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action::before {
    content: '';
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    background-image: var(--zr-total);
    filter: drop-shadow(0 0 4px rgba(255, 214, 160, .7));
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_tokens {
    font-family: var(--zr-label);
    color: var(--zr-dim);
}

/* 小铅笔打开的编辑弹窗：同样不变灰 */
#completion_prompt_manager_popup,
#completion_prompt_manager_popup .completion_prompt_manager_popup_entry {
    color: var(--zr-text);
    opacity: 1;
}

#completion_prompt_manager_popup .completion_prompt_manager_prompt {
    opacity: 1;
    color: var(--zr-text);
}

#completion_prompt_manager_popup textarea,
#completion_prompt_manager_popup input,
#completion_prompt_manager_popup select {
    opacity: 1;
    color: var(--zr-text);
}

/* ---------- 7. 弹窗 ---------- */
.popup {
    background: linear-gradient(170deg, #121a36, #070a18);
    border: 0;
    border-radius: 0;
    clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
    box-shadow: none;
    color: var(--zr-text);
}

.popup h3 {
    font: 900 calc(var(--mainFontSize) * 1.5)/1.4 var(--zr-cn-head);
    letter-spacing: .06em;
}

/* ---------- 8. 通知 toast ---------- */
body #toast-container>div {
    background-color: rgba(14, 18, 40, .97);
    color: var(--zr-text);
    border-radius: 0;
    box-shadow: 0 12px 30px rgba(0, 0, 0, .6);
    clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%, 0 10px);
    padding-left: 46px;
    font-family: var(--mainFontFamily);
}

body #toast-container .toast-success,
body #toast-container .toast-info,
body #toast-container .toast-warning,
body #toast-container .toast-error {
    background-color: rgba(14, 18, 40, .97);
}

#toast-container>.toast-success,
#toast-container>.toast-info {
    background-image: var(--zr-total) !important;
    background-size: 18px 18px;
    background-position: 16px center;
}

#toast-container>.toast-warning {
    background-image: var(--zr-cresc) !important;
    background-size: 18px 18px;
    background-position: 16px center;
}

#toast-container>.toast-error {
    background-image: var(--zr-sun) !important;
    background-size: 18px 18px;
    background-position: 16px center;
    box-shadow: inset 0 0 0 1px rgba(232, 90, 70, .5);
}

.toast-title {
    font-family: var(--zr-label);
    letter-spacing: .14em;
    color: var(--zr-gold);
}

/* ---------- 9. 移动端微调 ---------- */
@media screen and (max-width: 1000px) {
    :root {
        --zr-ava: 184px;
        --zr-uava: 108px;
    }

    .mes[is_user="false"] .name_text {
        font-size: 34px;
    }
}
